INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_CAUSES', 'PRE_.G8.FOUNDA.FIRE_SAFETY', 'pre_technical', 8, 'Name the causes of fire outbreaks at home, school and in the community', ARRAY['PRE_.G8.FOUNDA.FIRE_SAFETY.a']::text[], 'The child names causes of fire (a lit candle or match left unattended, faulty or overloaded electrical wiring, an unattended cooking fire or stove, careless disposal of cigarettes, leaking gas, children playing with matches, lightning and dry grass in the hot sun) and does not say fires have only natural causes. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a cause of fire","say which is a natural and which a human cause","say what a fire needs","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_PREVENT', 'PRE_.G8.FOUNDA.FIRE_SAFETY', 'pre_technical', 8, 'Pick ways to prevent fire outbreaks', ARRAY['PRE_.G8.FOUNDA.FIRE_SAFETY.b']::text[], 'The child picks ways to prevent fire (keep matches and lighters away from children, store paraffin, petrol and gas safely away from heat, never leave a stove or candle unattended, repair damaged wires, do not overload sockets, keep exits clear and have a fire drill) and does not block exits or store fuel near a stove. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the way to prevent a fire","say what to do with matches and fuel","say what to do with wiring and exits","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH', 'PRE_.G8.FOUNDA.FIRE_SAFETY', 'pre_technical', 8, 'Choose the right way to put out a fire: cooling, smothering or starving; the right extinguisher; when to raise the alarm and get out', ARRAY['PRE_.G8.FOUNDA.FIRE_SAFETY.c']::text[], 'Says that a fire needs heat, fuel and air, and puts it out by cooling (water on wood, paper or cloth), smothering (a lid, fire blanket or sand) or starving (turning off the gas, removing fuel); never water on burning oil or on an electrical fire (switch off the power, use a carbon dioxide or dry powder extinguisher); aims an extinguisher at the base; stop, drop and roll when clothes burn; raises the alarm and gets out first, calling 999 or 112. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["choose the method for a described fire","say why water is wrong for a fire","put the steps of a fire response in order"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.FOUNDA.DATA_SAFETY.DATA_THREATS', 'PRE_.G8.FOUNDA.DATA_SAFETY', 'pre_technical', 8, 'Say why data matters and name the threats to data on a device', ARRAY['PRE_.G8.FOUNDA.DATA_SAFETY.a', 'PRE_.G8.FOUNDA.DATA_SAFETY.b']::text[], 'The child says data (documents, photos, messages, schoolwork) is valuable because it is hard to replace and may be private, and names threats (viruses and other malware, theft or loss of the device, hackers, power failure, accidental deletion, a spoilt storage device), and does not say a virus can only come from the internet. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say why data is valuable","pick a threat to data","say what a virus does","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.FOUNDA.DATA_SAFETY.DATA_PROTECT', 'PRE_.G8.FOUNDA.DATA_SAFETY', 'pre_technical', 8, 'Pick ways to protect data on a device', ARRAY['PRE_.G8.FOUNDA.DATA_SAFETY.c', 'PRE_.G8.FOUNDA.DATA_SAFETY.d']::text[], 'The child picks ways to protect data (a strong password that is kept secret, a backup copy on another device, antivirus software kept up to date, locking the screen, not opening unknown links or attachments, keeping the device safe) and does not share a password or keep only one copy. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the way to protect data","say what a good password is","say what a backup is","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_INSTRUMENTS', 'PRE_.G8.COMMUN.PLANE_GEOMETRY', 'pre_technical', 8, 'Name the instruments used in technical drawing and what each does', ARRAY['PRE_.G8.COMMUN.PLANE_GEOMETRY.a']::text[], 'The child names the T-square (draws horizontal lines), set squares of 45 and 30/60 degrees (draw upright and slanted lines), the compass (draws circles and arcs), the protractor (measures angles), the ruler (measures lengths), the drawing board, a hard pencil for fine lines and the eraser, and does not mix them up. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the instrument for a task","say what the set square does","say what the compass does","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_LAYOUT', 'PRE_.G8.COMMUN.PLANE_GEOMETRY', 'pre_technical', 8, 'Say how a drawing sheet is laid out', ARRAY['PRE_.G8.COMMUN.PLANE_GEOMETRY.b']::text[], 'The child says a drawing sheet has a border (a frame drawn a little inside the edges), a title block (name, title, scale, date and sheet number) at the bottom right, a clear working area, and that A4 is 297 by 210 millimetres, and does not put the title block at the top or leave out the border. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the part of the sheet","say where the title block goes","say the size of an A4 sheet","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.GEOM_CONSTRUCT', 'PRE_.G8.COMMUN.PLANE_GEOMETRY', 'pre_technical', 8, 'Give the construction steps for combined shapes: bisecting a line, constructing 60 and 90 degree angles, a hexagon in a circle, and a slot with semicircular ends', ARRAY['PRE_.G8.COMMUN.PLANE_GEOMETRY.c']::text[], 'Gives the steps to bisect a line (compass set to more than half the line, arcs from both ends), construct 60 degrees (equal arcs from a point) and 90 degrees, a regular hexagon in a circle (sides equal to the radius), and a slot (centres on the centre line, radius half the width), and finds the wrong step in a described construction. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["put construction steps in order","find the radius or length a step needs","find the error in a described construction"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES', 'PRE_.G8.COMMUN.DIMENSIONING', 'pre_technical', 8, 'Name the parts of dimensioning and the types of dimension', ARRAY['PRE_.G8.COMMUN.DIMENSIONING.a', 'PRE_.G8.COMMUN.DIMENSIONING.b']::text[], 'The child names the dimension line (a thin line with arrowheads showing the size), extension lines (thin lines that stretch out from the object), the leader line (points to a note), the figure (written above the dimension line), the symbols for diameter and radius, and says sizes on drawings are normally in millimetres, and does not use the object line as a dimension line. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the line from its job","say where the figure is placed","pick the unit used","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_READ', 'PRE_.G8.COMMUN.DIMENSIONING', 'pre_technical', 8, 'Read and work out dimensions of given shapes', ARRAY['PRE_.G8.COMMUN.DIMENSIONING.c']::text[], 'The child reads a dimension from the drawing, adds the parts to get the overall length, subtracts to find a missing part, says the diameter is twice the radius, and keeps the unit with the answer. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["read the overall length","work out a missing dimension","work out the diameter from the radius","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.PLAIN_SCALE', 'PRE_.G8.COMMUN.PLAIN_SCALE_DRAWING', 'pre_technical', 8, 'Read a scale and work out real sizes from a drawing', ARRAY['PRE_.G8.COMMUN.PLAIN_SCALE_DRAWING.a', 'PRE_.G8.COMMUN.PLAIN_SCALE_DRAWING.b']::text[], 'The child says a scale such as 1:50 means one unit on the drawing stands for 50 of the same unit on the real object, multiplies a drawing length by the scale to get the real length and divides a real length by the scale to get the drawing length, knows 1:1 is full size and 2:1 is an enlargement, and keeps the units. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what a scale means","work out the real length","work out the drawing length","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.SCALE_CONVERT', 'PRE_.G8.COMMUN.PLAIN_SCALE_DRAWING', 'pre_technical', 8, 'Work out drawing sizes from real sizes for a given scale, and choose a scale that fits the sheet', ARRAY['PRE_.G8.COMMUN.PLAIN_SCALE_DRAWING.c']::text[], 'Converts the real size to millimetres, then divides by the scale for a reduction (1:20, 1:50) or multiplies for an enlargement (2:1), and chooses a scale that fits the drawing on the sheet (an 8 m room on A4 at 1:50, not 1:10). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["work out the drawing size","choose the scale that fits a sheet","find the error in a scale calculation"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.COMMUN.VISUAL_PROGRAMMING.VISUAL_PROG', 'PRE_.G8.COMMUN.VISUAL_PROGRAMMING', 'pre_technical', 8, 'Say what visual programming is and name its features and uses', ARRAY['PRE_.G8.COMMUN.VISUAL_PROGRAMMING.a', 'PRE_.G8.COMMUN.VISUAL_PROGRAMMING.b']::text[], 'The child says visual programming builds programs by snapping together blocks instead of typing code, names tools such as Scratch and App Inventor, names features (a block palette, a script area, a stage with sprites, events, loops and decisions), and says a loop repeats instructions. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a visual programming tool","pick a feature of such a tool","say what a loop or an event does","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.COMMUN.VISUAL_PROGRAMMING.VP_SEQUENCE', 'PRE_.G8.COMMUN.VISUAL_PROGRAMMING', 'pre_technical', 8, 'Build and read block instructions that solve a problem: order, events, loops and if-blocks in a visual programming application', ARRAY['PRE_.G8.COMMUN.VISUAL_PROGRAMMING.c']::text[], 'Says what a short block program does: blocks run from top to bottom under an event block (when green flag clicked), a repeat block repeats the blocks inside it the stated number of times (repeat 4: move, turn 90 draws a square), an if-block runs its blocks only when the condition is true; finds and fixes a wrong order or a missing event. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["say what a stack of blocks does","put blocks in order to solve a task","find the bug in a block program"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.MATERI.COMPOSITE_MATERIALS.COMPOSITE', 'PRE_.G8.MATERI.COMPOSITE_MATERIALS', 'pre_technical', 8, 'Say what composite materials are made of and what they are used for', ARRAY['PRE_.G8.MATERI.COMPOSITE_MATERIALS.a', 'PRE_.G8.MATERI.COMPOSITE_MATERIALS.b', 'PRE_.G8.MATERI.COMPOSITE_MATERIALS.c']::text[], 'The child says a composite material joins two or more materials to get a better one, and names concrete (cement, sand, ballast and water), reinforced concrete (concrete with steel bars), plywood (thin layers of wood glued crosswise), fibreglass (glass fibre in resin), and mud and straw bricks, with uses (buildings and slabs, furniture and boards, boat hulls and tanks, walls), and does not call concrete a single material. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the composite material","pick what it is made of","pick its use","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.MATERI.CERAMIC_MATERIALS.CERAMIC', 'PRE_.G8.MATERI.CERAMIC_MATERIALS', 'pre_technical', 8, 'Say what ceramic materials are, their properties and uses', ARRAY['PRE_.G8.MATERI.CERAMIC_MATERIALS.a', 'PRE_.G8.MATERI.CERAMIC_MATERIALS.b', 'PRE_.G8.MATERI.CERAMIC_MATERIALS.c']::text[], 'The child names ceramics (clay pots, bricks, floor and wall tiles, porcelain cups and sinks, electrical insulators), says they are hard, brittle (they break or crack when hit or dropped), resist heat and corrosion and do not conduct electricity, and says tiles, bricks, sinks and insulators use these properties. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the ceramic material","pick its property","pick its use","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_TOOLS', 'PRE_.G8.TOOLS_.CUTTING_TOOLS', 'pre_technical', 8, 'Choose the right cutting tool for a task and look after it', ARRAY['PRE_.G8.TOOLS_.CUTTING_TOOLS.a', 'PRE_.G8.TOOLS_.CUTTING_TOOLS.b', 'PRE_.G8.TOOLS_.CUTTING_TOOLS.d']::text[], 'The child picks the hacksaw for metal, the tenon saw for wood, the coping saw for curves, the chisel for shaping wood, the plane for smoothing wood, the tin snips for sheet metal and scissors for card and cloth, and picks care (keep blades sharp and clean, oil steel blades, store with guards, carry points down) and does not use a wood saw on metal. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the tool for a task","pick the way to care for the tool","say what a blunt tool does","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE', 'PRE_.G8.TOOLS_.CUTTING_TOOLS', 'pre_technical', 8, 'Give the safe way to use cutting tools: hold the work in a vice or clamp, cut away from the body, fit the blade the right way, start a cut gently, carry tools safely', ARRAY['PRE_.G8.TOOLS_.CUTTING_TOOLS.c']::text[], 'Says to hold the work in a vice or with a clamp, cut away from the body with both hands behind the edge, fit a hacksaw blade with its teeth pointing away from the handle, start a saw cut with light strokes then use long steady strokes, and carry edged tools pointing down; finds the unsafe step in a described job. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["pick the safe way to use a tool","find the unsafe step in a described job","say why a safety rule matters"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.TOOLS_.COMPUTER_SOFTWARE.SOFTWARE', 'PRE_.G8.TOOLS_.COMPUTER_SOFTWARE', 'pre_technical', 8, 'Sort software into system, application and utility and say what applications do', ARRAY['PRE_.G8.TOOLS_.COMPUTER_SOFTWARE.a', 'PRE_.G8.TOOLS_.COMPUTER_SOFTWARE.b', 'PRE_.G8.TOOLS_.COMPUTER_SOFTWARE.c']::text[], 'The child says system software runs the computer (an operating system such as Windows, Android or Linux), application software does a task for the user (a word processor for letters, a spreadsheet for calculations, a presentation program for slides, a browser for the web, a database for records), utility software looks after the computer (antivirus), and that software cannot be touched while hardware can. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["sort the software","pick the application for a task","say what an operating system does","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.ENTREP.BOOKKEEPING.BOOKKEEPING', 'PRE_.G8.ENTREP.BOOKKEEPING', 'pre_technical', 8, 'Say why a business keeps records and classify transactions', ARRAY['PRE_.G8.ENTREP.BOOKKEEPING.a', 'PRE_.G8.ENTREP.BOOKKEEPING.b']::text[], 'The child says a business keeps records to know its income, spending, profit or loss, to plan, to pay tax and to get loans, and sorts transactions into cash (paid now) and credit (paid later), income and expenditure, and assets (what a business owns), liabilities (what it owes) and capital (what the owner put in). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say why records matter","sort a transaction","sort cash and credit","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.ENTREP.BOOKKEEPING.FIN_STATEMENTS', 'PRE_.G8.ENTREP.BOOKKEEPING', 'pre_technical', 8, 'Prepare simple financial statements: the cash balance, gross and net profit, and assets = capital + liabilities', ARRAY['PRE_.G8.ENTREP.BOOKKEEPING.c']::text[], 'Works out the closing cash (opening cash + money received - money paid out), gross profit (sales - cost of goods sold), net profit (gross profit - expenses), and capital (assets - liabilities) for a small business, and finds the error in a statement that takes sales as profit or adds liabilities to assets. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["work out a cash balance","work out gross and net profit","find capital from assets and liabilities"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET', 'PRE_.G8.ENTREP.INCOME_AND_BUDGETING', 'pre_technical', 8, 'Name sources of income and say why and how to budget honestly', ARRAY['PRE_.G8.ENTREP.INCOME_AND_BUDGETING.a', 'PRE_.G8.ENTREP.INCOME_AND_BUDGETING.b', 'PRE_.G8.ENTREP.INCOME_AND_BUDGETING.d']::text[], 'The child names sources of income (wages or a salary, profit from a business, sales of farm produce, gifts and pocket money, interest), says a budget plans the income and spending so that needs come first and some is saved, and tells an honest budget from an unethical practice (hiding spending, using money meant for something else, borrowing without a plan to repay, cheating others). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick a source of income","say why a budget matters","pick an ethical or unethical practice","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET_PREPARE', 'PRE_.G8.ENTREP.INCOME_AND_BUDGETING', 'pre_technical', 8, 'Prepare a simple personal budget: income, needs before wants, planned saving, and the balance as surplus or deficit', ARRAY['PRE_.G8.ENTREP.INCOME_AND_BUDGETING.c']::text[], 'Lists income, plans needs before wants, puts saving in as an item at the start, totals the spending, and finds the balance: income - spending, a surplus when positive and a deficit when negative, and says how to fix a deficit (cut wants or raise income). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["find the balance of a budget","say whether a budget is in surplus or deficit","put budget items in order of need"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING', 'PRE_.G8.ENTREP.OF_GOODS_AND_SERVICES', 'pre_technical', 8, 'Say why a business markets, where it learns about the market and how it promotes goods', ARRAY['PRE_.G8.ENTREP.OF_GOODS_AND_SERVICES.a', 'PRE_.G8.ENTREP.OF_GOODS_AND_SERVICES.b', 'PRE_.G8.ENTREP.OF_GOODS_AND_SERVICES.c', 'PRE_.G8.ENTREP.OF_GOODS_AND_SERVICES.d', 'PRE_.G8.ENTREP.OF_GOODS_AND_SERVICES.e']::text[], 'The child says marketing helps a business find customers and sell, names sources of market information (asking customers, watching competitors, a survey, the internet, newspapers and radio), names factors in choosing a market (customer demand, price, location, competition, transport) and tools (a poster, radio, social media, samples, a price offer, word of mouth). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say why marketing matters","pick a source of market information","pick a factor in choosing a market","pick a tool of marketing"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION', 'PRE_.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN', 'pre_technical', 8, 'Say what intermediaries do, the channels of distribution and ethics in distribution', ARRAY['PRE_.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.a', 'PRE_.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.b', 'PRE_.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.c']::text[], 'The child names intermediaries (wholesalers who sell in bulk to retailers, retailers who sell to buyers, agents who bring buyers and sellers together), puts channels in order (producer to consumer; producer to retailer to consumer; producer to wholesaler to retailer to consumer), and picks ethical practices (honest weights and measures, fair prices, safe delivery, not hoarding) over unethical ones. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the intermediary","put the channel in order","pick the ethical practice","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
