INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING', 'PRET.G8.ENTREP.BOOKKEEPING.BOOKKEEPING', 'skill', 'essential', 'Records show what sells. Proposed, to confirm by a Pre-Technical Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_MEANING', 'skill', 'essential', 'What a business is, from Grade 7. Proposed, to confirm by a Pre-Technical Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING', 'PRET.G7.ENTREP.UNIT.UNIT_LOCATION', 'skill', 'essential', 'Nearness to the market, from Grade 7. Proposed, to confirm by a Pre-Technical Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION', 'PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING', 'skill', 'essential', 'Distribution gets marketed goods to customers. Proposed, to confirm by a Pre-Technical Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION', 'SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_NETWORKS', 'skill', 'essential', 'Transport networks, from Grade 6. Proposed, to confirm by a Pre-Technical Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_QUALITIES', 'skill', 'essential', 'Honesty as a quality of an entrepreneur, from Grade 7. Proposed, to confirm by a Pre-Technical Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_CAUSES.M_PT8_FC_NATURE_ONLY', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_CAUSES', 'Thinks fires start only from lightning or the sun.', '{"question":"Which is a common cause of fires in homes?","wrong_answer":"Only lightning","correct_answer":"A candle or stove left unattended"}'::jsonb, 'News of bush fires and lightning makes fire seem to come from nature, not from homes.', 'Offer "Only lightning" next to the right answer and ask the question again in a new context.', 'List the fires the learner has heard of near home and school; most started with a stove, candle, wire or match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_CAUSES.M_PT8_FC_WIRING', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_CAUSES', 'Thinks electricity cannot start a fire; only an open flame can.', '{"question":"Which of these can start a fire in a house?","wrong_answer":"Only an open flame; wires cannot","correct_answer":"Overloaded sockets or damaged wires"}'::jsonb, 'The learner pictures fire as flames and does not link it with electricity.', 'Offer "Only an open flame; wires cannot" beside "Overloaded sockets or damaged wires" and ask the child to choose.', 'Show a scorched socket and an overloaded adaptor; explain that too much current heats the wires.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_CAUSES.M_PT8_FC_FUEL', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_CAUSES', 'Thinks paraffin or gas is safe beside a lit stove because it is not burning yet.', '{"question":"Why is paraffin stored away from a lit stove?","wrong_answer":"There is no need; it only burns inside the lamp","correct_answer":"Its vapour can catch fire from the heat or flame"}'::jsonb, 'Paraffin and gas are not burning in their containers, so they seem safe.', 'Offer "There is no need; it only burns inside the lamp" beside "Its vapour can catch fire from the heat or flame" and ask the child to choose.', 'Explain that the vapour from paraffin, petrol and gas catches fire from a flame or spark nearby; store fuel away from heat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_PREVENT.M_PT8_FP_MATCHES', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_PREVENT', 'Leaves matches where children can reach them.', '{"question":"Where should matches be kept?","wrong_answer":"On the kitchen table","correct_answer":"Out of the reach of children"}'::jsonb, 'Matches are kept where adults use them, and the learner does not picture a small child reaching them.', 'Offer "On the kitchen table" next to the right answer and ask the question again in a new context.', 'Walk through a home picture and find a high, closed place for matches and lighters.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_PREVENT.M_PT8_FP_EXITS', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_PREVENT', 'Thinks locking or blocking exits keeps people safe during a fire.', '{"question":"Which action helps people escape from a fire?","wrong_answer":"Locking the exit door","correct_answer":"Keeping the exits clear"}'::jsonb, 'At home a locked door means safety from thieves, so locking seems safe.', 'Offer "Locking the exit door" next to the right answer and ask the question again in a new context.', 'Run a drill with one exit "blocked"; time how long it takes to get out. Keep exits clear and unlocked from inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_PREVENT.M_PT8_FP_UNATTENDED', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_PREVENT', 'Leaves a stove or candle burning while out of the room.', '{"question":"What should you do before leaving a room with a candle?","wrong_answer":"Leave it to burn","correct_answer":"Put it out"}'::jsonb, 'A candle or jiko looks steady and safe for a short time.', 'Offer "Leave it to burn" next to the right answer and ask the question again in a new context.', 'Agree a rule: put out a candle or switch off a stove every time you leave the room, even for a minute.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH.M_PT8_FE_WATER_OIL', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH', 'Pours water on a burning cooking pan.', '{"question":"Oil in a sufuria catches fire on the stove. What should be done?","wrong_answer":"Pour water on it at once","correct_answer":"Turn off the heat and cover the pan with a lid or fire blanket"}'::jsonb, 'Water puts out most fires the learner has seen, so it seems right for every fire.', 'Offer "Pour water on it at once" beside "Turn off the heat and cover the pan with a lid or fire blanket" and ask the child to choose.', 'Show a fire service video of water on burning oil (a fireball). Practise: heat off, cover, leave it covered.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH.M_PT8_FE_WATER_ELEC', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH', 'Throws water on an electrical fire while the power is still on.', '{"question":"A socket and its cable are on fire. What is the first thing to do?","wrong_answer":"Throw a bucket of water on it","correct_answer":"Switch off the power at the main switch if it is safe, then use a carbon dioxide or dry powder extinguisher"}'::jsonb, 'Water is the fire-fighting tool the learner knows.', 'Offer "Throw a bucket of water on it" beside "Switch off the power at the main switch if it is safe, then use a carbon dioxide or dry powder extinguisher" and ask the child to choose.', 'Explain that water carries electricity and can shock the person; show where the main switch is in the school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH.M_PT8_FE_AIM_TOP', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH', 'Aims a fire extinguisher at the tops of the flames.', '{"question":"Where do you aim a fire extinguisher?","wrong_answer":"At the tops of the flames","correct_answer":"At the base of the fire, sweeping from side to side"}'::jsonb, 'The flames are the part that looks dangerous, so they seem the target.', 'Offer "At the tops of the flames" beside "At the base of the fire, sweeping from side to side" and ask the child to choose.', 'Teach PASS: pull the pin, aim at the base, squeeze, sweep. The fuel at the base is what burns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH.M_PT8_FE_RUN', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH', 'Runs when their clothes catch fire.', '{"question":"A learner''s sleeve catches fire. What should she do?","wrong_answer":"Run to find water","correct_answer":"Stop, drop to the ground and roll, covering her face"}'::jsonb, 'Running away from danger feels natural.', 'Offer "Run to find water" beside "Stop, drop to the ground and roll, covering her face" and ask the child to choose.', 'Practise stop, drop and roll on a mat; explain that running fans the flames with air.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH.M_PT8_FE_FIGHT_FIRST', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_EXTINGUISH', 'Tries to fight a growing fire before raising the alarm or getting people out.', '{"question":"A fire is spreading in a store room. What comes first?","wrong_answer":"Fight it alone with a bucket","correct_answer":"Raise the alarm, get everyone out and call 999 or 112"}'::jsonb, 'The learner wants to be brave and stop the fire quickly.', 'Offer "Fight it alone with a bucket" beside "Raise the alarm, get everyone out and call 999 or 112" and ask the child to choose.', 'Walk the school fire drill: alarm, out by the nearest exit, to the assembly point, never go back in. Only trained adults fight small fires.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_CAUSES.M_PT8_FC_BURN_WIND', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_CAUSES', 'Thinks burning rubbish in the open is safe on a dry, windy day if someone stands nearby.', '{"question":"On a dry, windy day a farmer burns rubbish beside dry grass. What is the danger?","wrong_answer":"None, because he is standing nearby","correct_answer":"The wind can carry sparks to the grass and start a bush fire"}'::jsonb, 'The learner thinks a person watching can control any fire.', 'Offer "None, because he is standing nearby" beside "The wind can carry sparks to the grass and start a bush fire" and ask the child to choose.', 'Show how far sparks travel in wind; agree: never burn near dry grass or on a windy day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_PREVENT.M_PT8_FP_OVERLOAD', 'PRET.G8.FOUNDA.FIRE_SAFETY.FIRE_PREVENT', 'Thinks plugging many appliances into one adaptor is safe if it fits.', '{"question":"Which habit helps prevent electrical fires?","wrong_answer":"Plugging many appliances into one adaptor","correct_answer":"Not overloading sockets, and switching off when not in use"}'::jsonb, 'If the plugs fit, the learner thinks the socket can take them.', 'Offer "Plugging many appliances into one adaptor" beside "Not overloading sockets, and switching off when not in use" and ask the child to choose.', 'Show an adaptor with an iron, a kettle and a heater; explain that too much current heats the wires.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.DATA_SAFETY.DATA_THREATS.M_PT8_DT_NOT_IMPORTANT', 'PRET.G8.FOUNDA.DATA_SAFETY.DATA_THREATS', 'Thinks only companies'' data matters, not a learner''s photos, school work or contacts.', '{"question":"Why is the data on your phone worth protecting?","wrong_answer":"Only big companies need to protect data","correct_answer":"It is hard to replace and may be private"}'::jsonb, 'The learner hears about data breaches at banks and thinks their own photos and work do not count.', 'Offer "Only big companies need to protect data" beside "It is hard to replace and may be private" and ask the child to choose.', 'List what is on a learner''s phone or school account (photos, contacts, school work) and what losing it would mean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.DATA_SAFETY.DATA_THREATS.M_PT8_DT_VIRUS_ONLY', 'PRET.G8.FOUNDA.DATA_SAFETY.DATA_THREATS', 'Says a virus only comes from the internet.', '{"question":"How can a virus reach a computer?","wrong_answer":"Only through the internet","correct_answer":"Through the internet, flash disks and unknown files"}'::jsonb, 'Warnings about viruses are always about the internet.', 'Offer "Only through the internet" next to the right answer and ask the question again in a new context.', 'Show how a flash disk from a cyber café can carry a virus to the school computer; scan it first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.DATA_SAFETY.DATA_THREATS.M_PT8_DT_THEFT', 'PRET.G8.FOUNDA.DATA_SAFETY.DATA_THREATS', 'Thinks viruses are the only threat to data, forgetting theft, loss and damage.', '{"question":"Which is a threat to the data on a phone?","wrong_answer":"Only viruses","correct_answer":"Losing the phone or having it stolen, as well as viruses"}'::jsonb, 'Viruses are the threat talked about most, so theft, loss and damage are forgotten.', 'Offer "Only viruses" beside "Losing the phone or having it stolen, as well as viruses" and ask the child to choose.', 'List every way data can be lost: theft, loss, water, fire, power surges, deleting by mistake, viruses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.DATA_SAFETY.DATA_PROTECT.M_PT8_DP_PASSWORD_SHARE', 'PRET.G8.FOUNDA.DATA_SAFETY.DATA_PROTECT', 'Shares a password with a best friend because friends can be trusted.', '{"question":"What should you do with your password?","wrong_answer":"Share it with a friend","correct_answer":"Keep it secret"}'::jsonb, 'Friends are trusted, so sharing a password feels like friendship.', 'Offer "Share it with a friend" next to the right answer and ask the question again in a new context.', 'Ask what a friend could do with the account, even by mistake; friendships change but the account stays.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.DATA_SAFETY.DATA_PROTECT.M_PT8_DP_BACKUP', 'PRET.G8.FOUNDA.DATA_SAFETY.DATA_PROTECT', 'Thinks a device keeps files safe for ever, so a backup copy is not needed.', '{"question":"Why make a backup of an important file?","wrong_answer":"There is no need; the computer keeps every file safe","correct_answer":"So a copy is safe if the device is lost or fails"}'::jsonb, 'The learner has never lost a file and thinks devices keep files for ever.', 'Offer "There is no need; the computer keeps every file safe" beside "So a copy is safe if the device is lost or fails" and ask the child to choose.', 'Tell a story of an essay lost with a stolen phone; make a second copy on a flash disk or cloud account.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.DATA_SAFETY.DATA_PROTECT.M_PT8_DP_UNKNOWN_LINK', 'PRET.G8.FOUNDA.DATA_SAFETY.DATA_PROTECT', 'Opens a link from a stranger that promises a prize.', '{"question":"A stranger sends a link: \"You have won a phone, click here\". What do you do?","wrong_answer":"Click it to claim the prize","correct_answer":"Do not open it; delete it and tell an adult"}'::jsonb, 'A prize or a surprise feels exciting enough to click at once.', 'Offer "Click it to claim the prize" beside "Do not open it; delete it and tell an adult" and ask the child to choose.', 'Show a fake "you have won" message and list its clues; delete it and tell an adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.DATA_SAFETY.DATA_THREATS.M_PT8_DT_POWER', 'PRET.G8.FOUNDA.DATA_SAFETY.DATA_THREATS', 'Thinks a sudden power cut cannot harm data.', '{"question":"The power goes off while you are saving a file on a desktop computer. What can happen?","wrong_answer":"Nothing; data is always safe","correct_answer":"The file can be damaged or lost"}'::jsonb, 'The computer comes back on looking the same, so the learner thinks nothing happened.', 'Offer "Nothing; data is always safe" beside "The file can be damaged or lost" and ask the child to choose.', 'Explain that saving writes data step by step; a cut in the middle leaves it half written. Show a UPS (backup power).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.FOUNDA.DATA_SAFETY.DATA_PROTECT.M_PT8_DP_WEAK_PW', 'PRET.G8.FOUNDA.DATA_SAFETY.DATA_PROTECT', 'Uses an easy password such as a name, a birth date or 12345678.', '{"question":"Which makes the strongest password?","wrong_answer":"Your name and year of birth, so you never forget it","correct_answer":"A long mix of letters, numbers and symbols that has nothing to do with you"}'::jsonb, 'An easy password is easy to remember, and the learner does not picture someone guessing it.', 'Offer "Your name and year of birth, so you never forget it" beside "A long mix of letters, numbers and symbols that has nothing to do with you" and ask the child to choose.', 'Show how quickly a name or date can be guessed by someone who knows you; build a long passphrase from unrelated words and numbers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_INSTRUMENTS.M_PT8_DI_TOOL_MIX', 'PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_INSTRUMENTS', 'Thinks a set square draws circles, mixing it with the compass.', '{"question":"Which instrument draws circles?","wrong_answer":"A set square","correct_answer":"A compass"}'::jsonb, 'Set squares and compasses both sit in the geometry set and are learnt together.', 'Offer "A set square" next to the right answer and ask the question again in a new context.', 'Match each instrument to one job on the board; draw a circle with a compass and an angle with a set square.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_INSTRUMENTS.M_PT8_DI_TSQUARE', 'PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_INSTRUMENTS', 'Says the T-square measures angles.', '{"question":"What does the T-square draw?","wrong_answer":"Angles","correct_answer":"Horizontal lines"}'::jsonb, 'The T-square looks like a large ruler with a corner, so it seems to make angles.', 'Offer "Angles" next to the right answer and ask the question again in a new context.', 'Slide the T-square stock along the board edge and draw parallel horizontal lines; set squares rest on it for angles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_INSTRUMENTS.M_PT8_DI_PROTRACTOR', 'PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_INSTRUMENTS', 'Says the protractor measures length.', '{"question":"What does a protractor measure?","wrong_answer":"Length","correct_answer":"Angles"}'::jsonb, 'The protractor has a numbered scale like a ruler.', 'Offer "Length" next to the right answer and ask the question again in a new context.', 'Measure a corner with the protractor and a side with a rule; one gives degrees, the other millimetres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_LAYOUT.M_PT8_DL_TITLE_TOP', 'PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_LAYOUT', 'Puts the title block at the top.', '{"question":"Where is the title block of a drawing sheet?","wrong_answer":"At the top left","correct_answer":"At the bottom right"}'::jsonb, 'Titles in books and essays are at the top, so the learner puts the title block there.', 'Offer "At the top left" next to the right answer and ask the question again in a new context.', 'Look at a real drawing sheet: the title block is at the bottom right, where it can be read when sheets are folded or filed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_LAYOUT.M_PT8_DL_NO_BORDER', 'PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_LAYOUT', 'Leaves out the border, thinking the edge of the paper is enough.', '{"question":"Why is a border drawn on a drawing sheet?","wrong_answer":"It is not needed; the paper edge is enough","correct_answer":"It frames the drawing and leaves a margin for handling and filing"}'::jsonb, 'The edge of the paper seems to be a frame already.', 'Offer "It is not needed; the paper edge is enough" beside "It frames the drawing and leaves a margin for handling and filing" and ask the child to choose.', 'Draw a border 10 mm inside the edges; explain it frames the drawing and leaves a margin for handling and filing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_LAYOUT.M_PT8_DL_A4', 'PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_LAYOUT', 'Gives A3''s size, 420 by 297 mm, for A4.', '{"question":"What is the size of A4?","wrong_answer":"420 by 297 millimetres","correct_answer":"297 by 210 millimetres"}'::jsonb, 'A3 and A4 are learnt together, and the learner gives the larger size.', 'Offer "420 by 297 millimetres" next to the right answer and ask the question again in a new context.', 'Fold an A3 sheet in half: it makes two A4 sheets. Measure: A4 is 297 by 210 mm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.GEOM_CONSTRUCT.M_PT8_GC_HEX_SIDE', 'PRET.G8.COMMUN.PLANE_GEOMETRY.GEOM_CONSTRUCT', 'Steps off a hexagon in a circle with the diameter instead of the radius.', '{"question":"A regular hexagon is drawn in a circle of radius 30 mm. How long is each side?","wrong_answer":"60 mm, the diameter","correct_answer":"30 mm, the same as the radius"}'::jsonb, 'The diameter is the length the learner measures most often for a circle.', 'Offer "60 mm, the diameter" beside "30 mm, the same as the radius" and ask the child to choose.', 'Step the compass round the circle at the radius: it fits exactly six times. Join the points.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.GEOM_CONSTRUCT.M_PT8_GC_BISECT_SHORT', 'PRET.G8.COMMUN.PLANE_GEOMETRY.GEOM_CONSTRUCT', 'Sets the compass to less than half the line when bisecting, so the arcs never meet.', '{"question":"To bisect a line AB with a compass, the radius must be...","wrong_answer":"Less than half of AB","correct_answer":"More than half of AB"}'::jsonb, 'A small radius feels neater and safer.', 'Offer "Less than half of AB" beside "More than half of AB" and ask the child to choose.', 'Try both on the board: arcs with a short radius do not cross. Use a radius clearly more than half.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.GEOM_CONSTRUCT.M_PT8_GC_SLOT_RADIUS', 'PRET.G8.COMMUN.PLANE_GEOMETRY.GEOM_CONSTRUCT', 'Uses the full width of a slot as the radius of its semicircular ends.', '{"question":"A slot is 20 mm wide with semicircular ends. What radius draws each end?","wrong_answer":"20 mm, the full width","correct_answer":"10 mm, half the width"}'::jsonb, 'The width is the number given, so the learner uses it straight away.', 'Offer "20 mm, the full width" beside "10 mm, half the width" and ask the child to choose.', 'Draw the centre line, mark the two centres on it, and set the compass to half the width.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.GEOM_CONSTRUCT.M_PT8_GC_PROTRACTOR', 'PRET.G8.COMMUN.PLANE_GEOMETRY.GEOM_CONSTRUCT', 'Thinks a 60 degree angle can only be drawn with a protractor.', '{"question":"How is a 60 degree angle constructed with a compass and a ruler?","wrong_answer":"It cannot be; a protractor is needed","correct_answer":"Arc from the end of the line, then the same radius from where it cuts the line; join to the crossing"}'::jsonb, 'Angles have always been measured with a protractor in the learner''s lessons.', 'Offer "It cannot be; a protractor is needed" beside "Arc from the end of the line, then the same radius from where it cuts the line; join to the crossing" and ask the child to choose.', 'Construct 60 degrees with equal arcs and check it with a protractor; the two agree.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_INSTRUMENTS.M_PT8_DI_SET_SQUARE', 'PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_INSTRUMENTS', 'Uses the 45 degree set square to draw a 60 degree line.', '{"question":"Which set square draws a 60 degree line?","wrong_answer":"The 45 degree set square","correct_answer":"The 30-60 degree set square"}'::jsonb, 'Both are called set squares and look alike from a distance.', 'Offer "The 45 degree set square" beside "The 30-60 degree set square" and ask the child to choose.', 'Hold up both set squares, read the angles at their corners, and draw 30, 45 and 60 degree lines on the T-square.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_LAYOUT.M_PT8_DL_TSQUARE_EDGE', 'PRET.G8.COMMUN.PLANE_GEOMETRY.DRAW_LAYOUT', 'Slides the T-square stock along any edge of the drawing board, top or bottom.', '{"question":"Along which edge of the drawing board does the stock of the T-square slide?","wrong_answer":"Any edge, top or bottom","correct_answer":"One straight working edge (the left edge for a right-handed person)"}'::jsonb, 'All four edges look the same to the learner.', 'Offer "Any edge, top or bottom" beside "One straight working edge (the left edge for a right-handed person)" and ask the child to choose.', 'Show that only one edge is kept true; using others gives lines that are not parallel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES.M_PT8_DM_LINE_MIX', 'PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES', 'Mixes the dimension line with the extension line.', '{"question":"Which line has arrowheads and shows the size?","wrong_answer":"The extension line","correct_answer":"The dimension line"}'::jsonb, 'Both lines are thin and drawn at the same time.', 'Offer "The extension line" next to the right answer and ask the question again in a new context.', 'Label a dimensioned drawing: projection (extension) lines come out from the object; the dimension line between them has arrowheads and the number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES.M_PT8_DM_UNITS', 'PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES', 'Says drawings are dimensioned in metres.', '{"question":"In which unit are sizes normally given on a drawing?","wrong_answer":"Metres","correct_answer":"Millimetres"}'::jsonb, 'Building sizes are said in metres, so the learner expects them on drawings.', 'Offer "Metres" next to the right answer and ask the question again in a new context.', 'Look at a drawing of a small part: 45 means 45 mm. Most technical drawings use millimetres, stated in a note.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES.M_PT8_DM_OBJECT_LINE', 'PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES', 'Thinks the dimension line is the thick line that shows the shape.', '{"question":"Which line is thick and shows the shape?","wrong_answer":"The dimension line","correct_answer":"The object line"}'::jsonb, 'The dimension feels important, so the learner thinks its line must be the thick one.', 'Offer "The dimension line" next to the right answer and ask the question again in a new context.', 'Thick lines are only for the object outline; every added line (dimension, projection) is thin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_READ.M_PT8_DR_ADD', 'PRET.G8.COMMUN.DIMENSIONING.DIM_READ', 'Subtracts the sections instead of adding them to find the overall length.', '{"question":"A part is 30 mm and 45 mm long in two sections. What is the overall length?","wrong_answer":"15 mm","correct_answer":"75 mm"}'::jsonb, 'The learner subtracts the two numbers because "difference" sums are fresh in mind.', 'Offer "15 mm" next to the right answer and ask the question again in a new context.', 'Draw the two sections end to end and measure the whole; overall length = sum of the sections.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_READ.M_PT8_DR_DIAMETER', 'PRET.G8.COMMUN.DIMENSIONING.DIM_READ', 'Halves the radius to get the diameter instead of doubling it.', '{"question":"The radius of a circle is 20 mm. What is the diameter?","wrong_answer":"10 mm","correct_answer":"40 mm"}'::jsonb, 'The learner halves when moving from one circle measure to the other.', 'Offer "10 mm" next to the right answer and ask the question again in a new context.', 'Draw a circle with a line through the centre: the diameter is two radii.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_READ.M_PT8_DR_UNIT', 'PRET.G8.COMMUN.DIMENSIONING.DIM_READ', 'Does not look for the units note, so cannot tell whether 45 means millimetres or centimetres.', '{"question":"A drawing shows \"45\" with no unit beside it. How does the reader know the unit?","wrong_answer":"They guess from the size of the drawing","correct_answer":"From the note, such as ALL DIMENSIONS IN MILLIMETRES, in the title block"}'::jsonb, 'The learner sees bare numbers on a drawing and does not look for the note that gives the unit.', 'Offer "They guess from the size of the drawing" beside "From the note, such as ALL DIMENSIONS IN MILLIMETRES, in the title block" and ask the child to choose.', 'Find the note "ALL DIMENSIONS IN MILLIMETRES" in the title block; the unit is given once for the whole drawing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES.M_PT8_DM_TOUCH', 'PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES', 'Draws projection (extension) lines touching the outline of the object.', '{"question":"Where does a projection (extension) line start?","wrong_answer":"Touching the outline of the object","correct_answer":"A small gap away from the outline"}'::jsonb, 'The learner wants the line to look joined to the object.', 'Offer "Touching the outline of the object" beside "A small gap away from the outline" and ask the child to choose.', 'Show a drawing where touching lines make the outline look bigger; leave a small gap (about 1 to 2 mm).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES.M_PT8_DM_CHAIN_PARALLEL', 'PRET.G8.COMMUN.DIMENSIONING.DIM_TYPES', 'Mixes up chain and parallel dimensioning.', '{"question":"Which type of dimensioning measures every size from one datum edge?","wrong_answer":"Chain dimensioning","correct_answer":"Parallel (datum) dimensioning"}'::jsonb, 'Both types have rows of dimensions, and the names do not say how they are measured.', 'Offer "Chain dimensioning" beside "Parallel (datum) dimensioning" and ask the child to choose.', 'Draw both on the board: chain links one size to the next; parallel starts every size from the same edge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.DIMENSIONING.DIM_READ.M_PT8_DR_MEASURE_PAPER', 'PRET.G8.COMMUN.DIMENSIONING.DIM_READ', 'Measures a scaled drawing with a ruler instead of reading the dimension written on it.', '{"question":"A drawing at 1:2 shows a line 25 mm long on the paper, dimensioned 50. What is the real length?","wrong_answer":"25 mm, as measured on the paper","correct_answer":"50 mm, the dimension written"}'::jsonb, 'Measuring with a ruler feels more exact than trusting a number.', 'Offer "25 mm, as measured on the paper" beside "50 mm, the dimension written" and ask the child to choose.', 'Explain that dimensions always give the real size, whatever the scale; measure, then read the number, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.PLAIN_SCALE.M_PT8_SC_INVERT', 'PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.PLAIN_SCALE', 'Says 1:50 means the drawing is bigger than the object.', '{"question":"What does a scale of 1:50 mean?","wrong_answer":"The drawing is 50 times bigger","correct_answer":"One unit on the drawing stands for 50 on the object"}'::jsonb, 'The bigger number in 1:50 seems to belong to the drawing.', 'Offer "The drawing is 50 times bigger" next to the right answer and ask the question again in a new context.', 'Read 1:50 as "1 on the drawing stands for 50 on the object"; the drawing is smaller.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.PLAIN_SCALE.M_PT8_SC_CALC', 'PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.PLAIN_SCALE', 'Divides where he should multiply.', '{"question":"A line is 4 cm on a 1:50 drawing. What is the real length?","wrong_answer":"0.08 cm (4 divided by 50)","correct_answer":"4 times 50, which is 200 cm"}'::jsonb, 'Dividing feels right whenever a scale is used.', 'Offer "0.08 cm (4 divided by 50)" beside "4 times 50, which is 200 cm" and ask the child to choose.', 'Ask: the drawing is small, the real wall is big; to go from drawing to real, multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.PLAIN_SCALE.M_PT8_SC_ENLARGE', 'PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.PLAIN_SCALE', 'Says 2:1 is a reduction.', '{"question":"What does a scale of 2:1 mean?","wrong_answer":"A reduction","correct_answer":"An enlargement"}'::jsonb, 'The learner has only met reducing scales.', 'Offer "A reduction" next to the right answer and ask the question again in a new context.', 'Draw a small screw at 2:1; it comes out twice as big. The first number is the drawing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.SCALE_CONVERT.M_PT8_SV_UNITS', 'PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.SCALE_CONVERT', 'Divides metres by the scale without converting to millimetres first.', '{"question":"A wall 6 m long is drawn at 1:50. How long is it on the drawing?","wrong_answer":"0.12 mm","correct_answer":"120 mm"}'::jsonb, 'The learner divides the number given and forgets the unit.', 'Offer "0.12 mm" beside "120 mm" and ask the child to choose.', 'Write 6 m = 6,000 mm first, then divide by 50. Check: 120 mm fits on a page; 0.12 mm cannot be drawn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.SCALE_CONVERT.M_PT8_SV_MULTIPLY', 'PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.SCALE_CONVERT', 'Multiplies by the scale for a reduction.', '{"question":"A bench 2,000 mm long is drawn at 1:20. How long is it on the drawing?","wrong_answer":"40,000 mm","correct_answer":"100 mm"}'::jsonb, 'In other sums the bigger number is multiplied, and the learner does not check the size makes sense.', 'Offer "40,000 mm" beside "100 mm" and ask the child to choose.', 'Ask: is the drawing smaller or bigger than the bench? Smaller, so divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.SCALE_CONVERT.M_PT8_SV_ENLARGE', 'PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.SCALE_CONVERT', 'Divides for an enlargement scale such as 2:1.', '{"question":"A screw 15 mm long is drawn at 2:1. How long is it on the drawing?","wrong_answer":"7.5 mm","correct_answer":"30 mm"}'::jsonb, 'The learner has only met reducing scales and divides every time.', 'Offer "7.5 mm" beside "30 mm" and ask the child to choose.', 'Read 2:1 as "2 on the drawing for 1 on the object": twice as big, so multiply by 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.SCALE_CONVERT.M_PT8_SV_FIT', 'PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.SCALE_CONVERT', 'Chooses a scale that makes the drawing bigger than the sheet.', '{"question":"A room 8 m long is drawn on A4 paper (297 mm long). Which scale fits?","wrong_answer":"1:10, which makes it 800 mm","correct_answer":"1:50, which makes it 160 mm"}'::jsonb, 'A larger drawing seems clearer, and the learner does not check the sheet size.', 'Offer "1:10, which makes it 800 mm" beside "1:50, which makes it 160 mm" and ask the child to choose.', 'Work out the drawing length for 1:10, 1:20 and 1:50 and compare each with 297 mm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.PLAIN_SCALE.M_PT8_SC_DIVISIONS', 'PRET.G8.COMMUN.PLAIN_SCALE_DRAWING.PLAIN_SCALE', 'Thinks the small (secondary) divisions of a plain scale are at the right-hand end.', '{"question":"On a plain scale, where are the small (secondary) divisions?","wrong_answer":"At the right-hand end, after the last main division","correct_answer":"To the left of zero, in the first main division"}'::jsonb, 'On a ruler the numbers run left to right, so the learner expects the fine part at the end.', 'Offer "At the right-hand end, after the last main division" beside "To the left of zero, in the first main division" and ask the child to choose.', 'Construct a plain scale on the board: mark zero one main division in from the left, and divide that first division into tenths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.VISUAL_PROGRAMMING.VISUAL_PROG.M_PT8_VP_TEXT', 'PRET.G8.COMMUN.VISUAL_PROGRAMMING.VISUAL_PROG', 'Says visual programming means typing lines of code.', '{"question":"How are programs built in visual programming?","wrong_answer":"By typing lines of code","correct_answer":"By joining blocks"}'::jsonb, 'The learner has heard that programmers type code and expects all programming to look like that.', 'Offer "By typing lines of code" next to the right answer and ask the question again in a new context.', 'Open Scratch and drag three blocks together; nothing is typed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.VISUAL_PROGRAMMING.VISUAL_PROG.M_PT8_VP_TOOL', 'PRET.G8.COMMUN.VISUAL_PROGRAMMING.VISUAL_PROG', 'Thinks any computer program, such as a word processor, is a visual programming tool.', '{"question":"Which of these is a visual (block) programming tool?","wrong_answer":"Microsoft Word","correct_answer":"Scratch"}'::jsonb, 'Every program on a computer seems like a programming tool.', 'Offer "Microsoft Word" beside "Scratch" and ask the child to choose.', 'Sort programs into ones that make programs (Scratch, Blockly) and ones that do jobs (Word, a calculator).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.VISUAL_PROGRAMMING.VISUAL_PROG.M_PT8_VP_LOOP', 'PRET.G8.COMMUN.VISUAL_PROGRAMMING.VISUAL_PROG', 'Says a loop stops a program.', '{"question":"What does a loop do in a program?","wrong_answer":"Stops the program","correct_answer":"Repeats instructions"}'::jsonb, '"Loop" sounds like a knot or an ending.', 'Offer "Stops the program" next to the right answer and ask the question again in a new context.', 'Make a sprite repeat a dance step 5 times with a repeat block; count the repeats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.VISUAL_PROGRAMMING.VP_SEQUENCE.M_PT8_VS_ORDER', 'PRET.G8.COMMUN.VISUAL_PROGRAMMING.VP_SEQUENCE', 'Thinks the order of blocks in a stack does not matter.', '{"question":"A sprite must walk to a door and then open it. The blocks are: \"open door\", then \"move 10 steps\". What happens?","wrong_answer":"The same as the other order","correct_answer":"It opens the door before it walks there; the order is wrong"}'::jsonb, 'The learner sees the right blocks are there and thinks that is enough.', 'Offer "The same as the other order" beside "It opens the door before it walks there; the order is wrong" and ask the child to choose.', 'Act it out: one learner follows the blocks exactly as stacked. Then swap them and act again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.VISUAL_PROGRAMMING.VP_SEQUENCE.M_PT8_VS_LOOP', 'PRET.G8.COMMUN.VISUAL_PROGRAMMING.VP_SEQUENCE', 'Thinks a repeat block runs its blocks only once.', '{"question":"repeat 4 [move 50 steps, turn 90 degrees]. What does the sprite draw?","wrong_answer":"One straight line","correct_answer":"A square"}'::jsonb, 'The learner reads the blocks inside once and ignores the number on the repeat.', 'Offer "One straight line" beside "A square" and ask the child to choose.', 'Walk it on the floor: four times, move and turn. Draw each step as you go.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.VISUAL_PROGRAMMING.VP_SEQUENCE.M_PT8_VS_NO_EVENT', 'PRET.G8.COMMUN.VISUAL_PROGRAMMING.VP_SEQUENCE', 'Expects blocks to run when the flag is clicked though they are not under an event block.', '{"question":"Blocks sit in the scripts area but not under \"when green flag clicked\". What happens when the flag is clicked?","wrong_answer":"They run","correct_answer":"They do not run; they need the event block on top"}'::jsonb, 'The blocks are on the screen, so the learner thinks the program will use them.', 'Offer "They run" beside "They do not run; they need the event block on top" and ask the child to choose.', 'Click the flag with and without the event block on top; see which stack runs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.VISUAL_PROGRAMMING.VP_SEQUENCE.M_PT8_VS_IF_ALWAYS', 'PRET.G8.COMMUN.VISUAL_PROGRAMMING.VP_SEQUENCE', 'Thinks the blocks inside an if-block always run.', '{"question":"if touching wall then say \"Ouch\". The sprite is not touching the wall. What happens?","wrong_answer":"It says \"Ouch\" anyway","correct_answer":"Nothing; the blocks inside run only when the condition is true"}'::jsonb, 'The learner reads the inside blocks as plain instructions.', 'Offer "It says "Ouch" anyway" beside "Nothing; the blocks inside run only when the condition is true" and ask the child to choose.', 'Run it twice, once away from the wall and once touching it. Say "if" means "only when".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.COMMUN.VISUAL_PROGRAMMING.VISUAL_PROG.M_PT8_VP_SPRITE', 'PRET.G8.COMMUN.VISUAL_PROGRAMMING.VISUAL_PROG', 'Thinks a sprite is the background of the stage.', '{"question":"In Scratch, what is a sprite?","wrong_answer":"The background of the stage","correct_answer":"A character or object that the blocks control"}'::jsonb, 'The stage and sprite appear together on the screen and the learner mixes the names.', 'Offer "The background of the stage" beside "A character or object that the blocks control" and ask the child to choose.', 'Point to the stage (backdrop) and to the cat (sprite); give each its own blocks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.MATERI.COMPOSITE_MATERIALS.COMPOSITE.M_PT8_CM_SINGLE', 'PRET.G8.MATERI.COMPOSITE_MATERIALS.COMPOSITE', 'Says concrete is a single material.', '{"question":"What is concrete made of?","wrong_answer":"One material only","correct_answer":"Cement, sand, ballast and water"}'::jsonb, 'Concrete looks like one grey solid when it is set.', 'Offer "One material only" next to the right answer and ask the question again in a new context.', 'Mix a small batch: cement, sand, ballast and water; break an old piece to see the stones inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.MATERI.COMPOSITE_MATERIALS.COMPOSITE.M_PT8_CM_PLYWOOD', 'PRET.G8.MATERI.COMPOSITE_MATERIALS.COMPOSITE', 'Says plywood is one solid piece of wood.', '{"question":"How is plywood made?","wrong_answer":"From one solid piece of wood","correct_answer":"From thin layers of wood glued crosswise"}'::jsonb, 'Plywood looks like one board from the face.', 'Offer "From one solid piece of wood" next to the right answer and ask the question again in a new context.', 'Look at the edge: thin layers (veneers) glued with the grain crossing, which makes it strong and stops splitting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.MATERI.COMPOSITE_MATERIALS.COMPOSITE.M_PT8_CM_USE', 'PRET.G8.MATERI.COMPOSITE_MATERIALS.COMPOSITE', 'Thinks reinforced concrete is used for small, light items, not for heavy structures.', '{"question":"What is reinforced concrete mainly used for?","wrong_answer":"Light window frames","correct_answer":"Beams, columns and floor slabs of buildings"}'::jsonb, 'The learner does not link the strength of reinforced concrete with heavy structures.', 'Offer "Light window frames" beside "Beams, columns and floor slabs of buildings" and ask the child to choose.', 'Visit or show a building site: beams, columns and slabs are reinforced concrete.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.MATERI.COMPOSITE_MATERIALS.COMPOSITE.M_PT8_CM_STEEL_WEIGHT', 'PRET.G8.MATERI.COMPOSITE_MATERIALS.COMPOSITE', 'Thinks steel bars are put in concrete to make it heavier.', '{"question":"Why are steel bars put inside concrete?","wrong_answer":"To make it heavier","correct_answer":"Concrete is weak when pulled or bent; the steel takes the pull"}'::jsonb, 'Heavy things seem strong, so the learner thinks weight is the point.', 'Offer "To make it heavier" beside "Concrete is weak when pulled or bent; the steel takes the pull" and ask the child to choose.', 'Bend a thin slab of plain mortar until it cracks underneath; explain the steel goes where the pulling is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.MATERI.CERAMIC_MATERIALS.CERAMIC.M_PT8_CR_BRITTLE', 'PRET.G8.MATERI.CERAMIC_MATERIALS.CERAMIC', 'Says ceramics do not break.', '{"question":"What happens when a clay pot is dropped?","wrong_answer":"It stays whole, because ceramic is hard","correct_answer":"It breaks, because ceramic is brittle"}'::jsonb, 'Hard materials feel strong, so the learner expects them to survive a fall.', 'Offer "It stays whole, because ceramic is hard" beside "It breaks, because ceramic is brittle" and ask the child to choose.', 'Explain hard and brittle: a ceramic resists scratching but cracks when hit. Show a broken cup.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.MATERI.CERAMIC_MATERIALS.CERAMIC.M_PT8_CR_CONDUCT', 'PRET.G8.MATERI.CERAMIC_MATERIALS.CERAMIC', 'Says ceramics conduct electricity.', '{"question":"Why are ceramics used as electrical insulators?","wrong_answer":"They conduct electricity well","correct_answer":"They do not conduct electricity"}'::jsonb, 'Ceramics are hard and smooth like some metals.', 'Offer "They conduct electricity well" next to the right answer and ask the question again in a new context.', 'Show a porcelain insulator on a power pole holding the live wire away from the pole.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.MATERI.CERAMIC_MATERIALS.CERAMIC.M_PT8_CR_METAL', 'PRET.G8.MATERI.CERAMIC_MATERIALS.CERAMIC', 'Thinks a ceramic tile is plastic because it is smooth and shiny.', '{"question":"A floor tile is smooth and shiny. What group of materials is it?","wrong_answer":"Plastic","correct_answer":"Ceramic (fired clay)"}'::jsonb, 'A tile is smooth and shiny like plastic, so it is sorted by look.', 'Offer "Plastic" beside "Ceramic (fired clay)" and ask the child to choose.', 'Tap a tile and a plastic sheet; heat-test is not done. Trace the tile back to fired clay.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.MATERI.CERAMIC_MATERIALS.CERAMIC.M_PT8_CR_SUN_DRY', 'PRET.G8.MATERI.CERAMIC_MATERIALS.CERAMIC', 'Thinks soft clay becomes a hard ceramic just by drying in the sun.', '{"question":"What turns soft clay into a hard ceramic pot?","wrong_answer":"Drying it in the sun","correct_answer":"Firing it at a high temperature in a kiln"}'::jsonb, 'Sun-dried mud blocks harden, so the learner thinks all clay hardens that way.', 'Offer "Drying it in the sun" beside "Firing it at a high temperature in a kiln" and ask the child to choose.', 'Soak a sun-dried clay piece and a fired piece; the dried one softens, the fired one stays hard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_TOOLS.M_PT8_CT_WOOD_METAL', 'PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_TOOLS', 'Uses a wood saw on metal.', '{"question":"Which saw cuts metal?","wrong_answer":"A tenon saw","correct_answer":"A hacksaw"}'::jsonb, 'Both are saws, and the learner does not look at the teeth.', 'Offer "A tenon saw" next to the right answer and ask the question again in a new context.', 'Compare the teeth: a tenon saw has bigger teeth for wood; a hacksaw has fine hard teeth for metal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_TOOLS.M_PT8_CT_PLANE', 'PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_TOOLS', 'Says a chisel smooths a large surface.', '{"question":"Which tool smooths a wooden board?","wrong_answer":"A chisel","correct_answer":"A plane"}'::jsonb, 'A chisel and a plane both have a sharp flat blade.', 'Offer "A chisel" next to the right answer and ask the question again in a new context.', 'Plane a board to show long smooth shavings; chisel a joint to show cutting out small parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_TOOLS.M_PT8_CT_BLUNT', 'PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_TOOLS', 'Thinks a blunt tool is safer.', '{"question":"Why should a cutting tool be kept sharp?","wrong_answer":"A blunt tool is safer","correct_answer":"A sharp tool cuts easily and slips less"}'::jsonb, 'A blunt edge seems less able to cut a person.', 'Offer "A blunt tool is safer" next to the right answer and ask the question again in a new context.', 'Explain that a blunt tool needs more force and slips; compare cutting card with sharp and blunt scissors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE.M_PT8_CU_TOWARDS', 'PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE', 'Cuts with a chisel or knife towards the body or the holding hand.', '{"question":"In which direction should a chisel or knife cut?","wrong_answer":"Towards the body, for more control","correct_answer":"Away from the body, with both hands behind the cutting edge"}'::jsonb, 'Pulling a blade towards oneself feels more controlled.', 'Offer "Towards the body, for more control" beside "Away from the body, with both hands behind the cutting edge" and ask the child to choose.', 'Show the path the blade takes if it slips in each direction; agree the rule and practise on a clamped scrap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE.M_PT8_CU_HAND_HOLD', 'PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE', 'Holds a small piece in one hand while sawing or chiselling it with the other.', '{"question":"How is a small piece of wood held while it is sawn?","wrong_answer":"In one hand while the other hand saws","correct_answer":"Clamped in a vice or with a G-clamp"}'::jsonb, 'It is quicker than setting up a vice.', 'Offer "In one hand while the other hand saws" beside "Clamped in a vice or with a G-clamp" and ask the child to choose.', 'Show how a saw jumps at the start of a cut; clamp the work and saw with the free hand guiding safely.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE.M_PT8_CU_BLADE_BACK', 'PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE', 'Fits a hacksaw blade with its teeth pointing towards the handle.', '{"question":"Which way do the teeth of a hacksaw blade point?","wrong_answer":"Towards the handle","correct_answer":"Away from the handle, so it cuts on the forward stroke"}'::jsonb, 'The learner does not look at the teeth and fits the blade either way.', 'Offer "Towards the handle" beside "Away from the handle, so it cuts on the forward stroke" and ask the child to choose.', 'Look at the teeth with a magnifier; fit the blade so they point forward and feel the cut on the push.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE.M_PT8_CU_PRESS_HARD', 'PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE', 'Starts a saw cut by pressing hard with fast short strokes.', '{"question":"How should you start a saw cut?","wrong_answer":"Press hard with fast short strokes","correct_answer":"Light strokes to start a groove, then long steady strokes"}'::jsonb, 'Pressing hard feels like it will cut faster.', 'Offer "Press hard with fast short strokes" beside "Light strokes to start a groove, then long steady strokes" and ask the child to choose.', 'Start a cut with a thumb guiding the blade (above the teeth) and light strokes; then use the full length of the blade.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE.M_PT8_CU_CARRY', 'PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_USE', 'Carries a chisel or saw with the edge up or in a pocket.', '{"question":"How is a chisel carried in the workshop?","wrong_answer":"In a pocket, blade up","correct_answer":"In the hand by the side, edge pointing down, walking"}'::jsonb, 'A pocket keeps the hands free.', 'Offer "In a pocket, blade up" beside "In the hand by the side, edge pointing down, walking" and ask the child to choose.', 'Show the injury a blade in a pocket can cause in a fall; practise carrying tools pointing down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_TOOLS.M_PT8_CT_RIP_CROSS', 'PRET.G8.TOOLS_.CUTTING_TOOLS.CUT_TOOLS', 'Uses a rip saw to cut across the grain of wood.', '{"question":"Which saw cuts wood across the grain?","wrong_answer":"A rip saw","correct_answer":"A cross-cut saw"}'::jsonb, 'Both are hand saws and look alike.', 'Offer "A rip saw" beside "A cross-cut saw" and ask the child to choose.', 'Show the grain on a plank; cross-cut goes across it, rip goes along it. Look at the tooth shapes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.COMPUTER_SOFTWARE.SOFTWARE.M_PT8_SW_TOUCH', 'PRET.G8.TOOLS_.COMPUTER_SOFTWARE.SOFTWARE', 'Says software can be touched.', '{"question":"Which can you touch?","wrong_answer":"Software","correct_answer":"Hardware"}'::jsonb, 'Software comes in a box or is "installed", so it seems like a thing.', 'Offer "Software" next to the right answer and ask the question again in a new context.', 'Point to the screen (hardware) and the program on it (software); you can touch the screen, not the program.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.COMPUTER_SOFTWARE.SOFTWARE.M_PT8_SW_OS', 'PRET.G8.TOOLS_.COMPUTER_SOFTWARE.SOFTWARE', 'Calls an application the operating system.', '{"question":"Which is an operating system?","wrong_answer":"A word processor","correct_answer":"Windows"}'::jsonb, 'The word processor is the program the learner uses most.', 'Offer "A word processor" next to the right answer and ask the question again in a new context.', 'List programs: Windows, Android (run the computer); Word, Excel (do jobs for the user).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.COMPUTER_SOFTWARE.SOFTWARE.M_PT8_SW_APP', 'PRET.G8.TOOLS_.COMPUTER_SOFTWARE.SOFTWARE', 'Picks the wrong application for the task.', '{"question":"Which application is used for calculations in a table?","wrong_answer":"A word processor","correct_answer":"A spreadsheet"}'::jsonb, 'The learner uses a word processor for everything, including tables.', 'Offer "A word processor" next to the right answer and ask the question again in a new context.', 'Try 12 + 8 in a spreadsheet cell with a formula; a word processor does not calculate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.TOOLS_.COMPUTER_SOFTWARE.SOFTWARE.M_PT8_SW_UTILITY', 'PRET.G8.TOOLS_.COMPUTER_SOFTWARE.SOFTWARE', 'Thinks an antivirus is application software like a game.', '{"question":"An antivirus program belongs to which category of software?","wrong_answer":"Application software, like a game","correct_answer":"Utility (system) software that protects and maintains the computer"}'::jsonb, 'It is installed and opened like any app.', 'Offer "Application software, like a game" beside "Utility (system) software that protects and maintains the computer" and ask the child to choose.', 'Sort programs by who they serve: the user''s jobs (applications) or the computer''s care (utilities, operating system).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.BOOKKEEPING.BOOKKEEPING.M_PT8_BK_BIG_ONLY', 'PRET.G8.ENTREP.BOOKKEEPING.BOOKKEEPING', 'Says only big businesses keep records.', '{"question":"Which businesses should keep records?","wrong_answer":"Only big businesses","correct_answer":"Every business, big or small"}'::jsonb, 'Small traders around the learner keep money in their heads, so records seem to be for big firms.', 'Offer "Only big businesses" next to the right answer and ask the question again in a new context.', 'Ask a small trader how she knows her profit; show a simple daily sales book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.BOOKKEEPING.BOOKKEEPING.M_PT8_BK_ASSET', 'PRET.G8.ENTREP.BOOKKEEPING.BOOKKEEPING', 'Mixes an asset with a liability.', '{"question":"A loan owed to a supplier is...","wrong_answer":"An asset","correct_answer":"A liability"}'::jsonb, 'Both words are new and the learner sorts by guess.', 'Offer "An asset" next to the right answer and ask the question again in a new context.', 'Two columns: owned by the business (assets: stock, cash, equipment) and owed by the business (liabilities: loans, suppliers).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.BOOKKEEPING.BOOKKEEPING.M_PT8_BK_CASH', 'PRET.G8.ENTREP.BOOKKEEPING.BOOKKEEPING', 'Calls a credit sale a cash sale.', '{"question":"A customer takes goods and will pay next week. What is this?","wrong_answer":"A cash sale","correct_answer":"A credit sale"}'::jsonb, 'The goods left the shop, so the sale feels finished as cash.', 'Offer "A cash sale" next to the right answer and ask the question again in a new context.', 'Ask "was the money paid now?" Yes: cash sale. Later: credit sale, and the customer is a debtor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.BOOKKEEPING.FIN_STATEMENTS.M_PT8_FS_SALES_PROFIT', 'PRET.G8.ENTREP.BOOKKEEPING.FIN_STATEMENTS', 'Takes total sales as the profit.', '{"question":"Sales 20,000 shillings, cost of goods sold 12,000, expenses 3,000. What is the net profit?","wrong_answer":"20,000 shillings","correct_answer":"5,000 shillings"}'::jsonb, 'All the money coming in feels like what the business earned.', 'Offer "20,000 shillings" beside "5,000 shillings" and ask the child to choose.', 'Lay it out: sales - cost of goods = gross profit (8,000); gross profit - expenses = net profit (5,000).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.BOOKKEEPING.FIN_STATEMENTS.M_PT8_FS_GROSS_NET', 'PRET.G8.ENTREP.BOOKKEEPING.FIN_STATEMENTS', 'Gives the gross profit as the net profit, forgetting the expenses.', '{"question":"Gross profit 8,000 shillings, expenses (rent, transport) 3,000. What is the net profit?","wrong_answer":"8,000 shillings","correct_answer":"5,000 shillings"}'::jsonb, 'The learner stops at the first profit line.', 'Offer "8,000 shillings" beside "5,000 shillings" and ask the child to choose.', 'List the expenses of a kiosk (rent, transport, power); take them away from gross profit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.BOOKKEEPING.FIN_STATEMENTS.M_PT8_FS_CAPITAL_ADD', 'PRET.G8.ENTREP.BOOKKEEPING.FIN_STATEMENTS', 'Adds liabilities to assets to find capital.', '{"question":"A business has assets of 50,000 shillings and liabilities of 10,000. What is the capital?","wrong_answer":"60,000 shillings","correct_answer":"40,000 shillings"}'::jsonb, 'Adding is the first operation the learner tries with two amounts.', 'Offer "60,000 shillings" beside "40,000 shillings" and ask the child to choose.', 'Write assets = capital + liabilities; what the business owns, less what it owes, belongs to the owner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.BOOKKEEPING.FIN_STATEMENTS.M_PT8_FS_CASH_ADD', 'PRET.G8.ENTREP.BOOKKEEPING.FIN_STATEMENTS', 'Adds money paid out to the cash balance.', '{"question":"Cash at the start 2,000, received 5,000, paid out 3,500. What is the cash at the end?","wrong_answer":"10,500 shillings","correct_answer":"3,500 shillings"}'::jsonb, 'The learner adds every amount listed.', 'Offer "10,500 shillings" beside "3,500 shillings" and ask the child to choose.', 'Use a cash book with two sides: money in, money out. Closing cash = opening + in - out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.BOOKKEEPING.BOOKKEEPING.M_PT8_BK_DRAWINGS', 'PRET.G8.ENTREP.BOOKKEEPING.BOOKKEEPING', 'Records money the owner takes for the family as a business expense.', '{"question":"The owner takes 500 shillings from the till to buy food for her family. How is it recorded?","wrong_answer":"As a business expense","correct_answer":"As drawings (money taken out by the owner)"}'::jsonb, 'The money left the business, and every payment out seems to be an expense.', 'Offer "As a business expense" beside "As drawings (money taken out by the owner)" and ask the child to choose.', 'Separate business costs (rent, stock, transport) from the owner''s own use (drawings); drawings reduce capital, not profit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET.M_PT8_BU_INCOME', 'PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET', 'Lists a bill, which is money going out, as a source of income.', '{"question":"Which is a source of income?","wrong_answer":"A bill","correct_answer":"A salary"}'::jsonb, 'Bills and income both involve money changing hands, and the learner does not ask which way it flows.', 'Offer "A bill" next to the right answer and ask the question again in a new context.', 'Draw two arrows: money in (salary, sales, rent received, pocket money) and money out (bills, rent paid, food).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET.M_PT8_BU_NO_NEED', 'PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET', 'Thinks a budget is not needed when there is only a little money.', '{"question":"Why make a budget if you have only a little money?","wrong_answer":"Budgets are only for people with a lot of money","correct_answer":"To plan the little money so needs are met and some is saved"}'::jsonb, 'Budgets sound like something for people with a lot of money.', 'Offer "Budgets are only for people with a lot of money" beside "To plan the little money so needs are met and some is saved" and ask the child to choose.', 'Show a learner with 300 shillings for a term planning fare, pens and saving; without a plan it runs out in week 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET.M_PT8_BU_UNETHICAL', 'PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET', 'Thinks moving budget money to personal use is fine if the total stays the same.', '{"question":"A club treasurer writes \"snacks 500\" in the budget but spends it on airtime for herself. What is this?","wrong_answer":"Fine, as long as the total stays the same","correct_answer":"Unethical: misusing the money and hiding it"}'::jsonb, 'The learner thinks honesty is kept if the totals still add up.', 'Offer "Fine, as long as the total stays the same" beside "Unethical: misusing the money and hiding it" and ask the child to choose.', 'Discuss trust in a club or family: money must be used as the budget says, and changes are agreed openly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET_PREPARE.M_PT8_BP_DEFICIT', 'PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET_PREPARE', 'Calls a budget that spends more than its income balanced.', '{"question":"Income 3,000 shillings, planned spending 3,400. What is this budget?","wrong_answer":"Balanced","correct_answer":"In deficit by 400 shillings"}'::jsonb, 'The learner checks only that every item has a number.', 'Offer "Balanced" beside "In deficit by 400 shillings" and ask the child to choose.', 'Always subtract: income - spending. A negative answer is a deficit; cut wants until it is zero or more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET_PREPARE.M_PT8_BP_WANTS_FIRST', 'PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET_PREPARE', 'Puts wants into a budget before needs.', '{"question":"Which item goes into a learner''s budget first?","wrong_answer":"A new phone cover","correct_answer":"Bus fare to school"}'::jsonb, 'Wants are more exciting to plan for.', 'Offer "A new phone cover" beside "Bus fare to school" and ask the child to choose.', 'Sort budget cards into needs and wants; fill the budget with needs first, then wants if money is left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET_PREPARE.M_PT8_BP_SAVE_LAST', 'PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET_PREPARE', 'Saves only whatever is left at the end of the month.', '{"question":"When should saving be put into a budget?","wrong_answer":"Only if money is left at the end","correct_answer":"At the start, as a planned item"}'::jsonb, 'Saving feels like leftovers, not a need.', 'Offer "Only if money is left at the end" beside "At the start, as a planned item" and ask the child to choose.', 'Compare two months: saving last (nothing left) and saving first (100 put away); "pay yourself first".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET_PREPARE.M_PT8_BP_SURPLUS_LOSS', 'PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET_PREPARE', 'Calls money left over in a budget a loss.', '{"question":"Income 5,000 shillings, spending 4,200. What is the 800 shillings?","wrong_answer":"A loss","correct_answer":"A surplus, which can be saved"}'::jsonb, 'Money "left over" sounds like money not used, so it feels wasted.', 'Offer "A loss" beside "A surplus, which can be saved" and ask the child to choose.', 'Draw income and spending bars; the part of income not spent is a surplus, ready to save.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET.M_PT8_BU_LOAN_INCOME', 'PRET.G8.ENTREP.INCOME_AND_BUDGETING.BUDGET', 'Treats a loan as income that can be spent freely.', '{"question":"Wanjiru borrows 1,000 shillings. Should she plan it as free income in her budget?","wrong_answer":"Yes, it is extra money to spend","correct_answer":"No, it must be paid back; plan the repayment"}'::jsonb, 'Borrowed money is in the hand, so it feels like the learner''s own.', 'Offer "Yes, it is extra money to spend" beside "No, it must be paid back; plan the repayment" and ask the child to choose.', 'Show a budget with the loan as money in and the repayment (with any interest) as money out later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING.M_PT8_MK_SELLING_ONLY', 'PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING', 'Says marketing is only selling at the till.', '{"question":"What does marketing do?","wrong_answer":"Only takes the money at the till","correct_answer":"Finds customers and tells them about goods"}'::jsonb, 'Selling at the till is the part of marketing the learner sees.', 'Offer "Only takes the money at the till" next to the right answer and ask the question again in a new context.', 'Trace how a customer hears of a new shop (poster, friend, radio) before buying: that is marketing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING.M_PT8_MK_INFO', 'PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING', 'Relies on the owner''s own taste instead of asking customers.', '{"question":"What is the most reliable way for a new bakery to find out what customers want?","wrong_answer":"Make what the owner likes best","correct_answer":"Ask customers through a short survey or interviews"}'::jsonb, 'The owner''s own taste feels like a good guide to what others want.', 'Offer "Make what the owner likes best" beside "Ask customers through a short survey or interviews" and ask the child to choose.', 'Run a short class survey on snacks; compare the result with one person''s guess.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING.M_PT8_MK_FACTOR', 'PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING', 'Ignores how many customers want the goods and can pay when choosing a market.', '{"question":"Which factor matters most when choosing where to sell school uniforms?","wrong_answer":"The seller''s favourite town","correct_answer":"Many schools nearby, with customers who can pay"}'::jsonb, 'The learner thinks of the seller''s wishes, not the buyers.', 'Offer "The seller''s favourite town" beside "Many schools nearby, with customers who can pay" and ask the child to choose.', 'List what a market needs: customers who want the goods and can pay, access, competition, cost of reaching it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING.M_PT8_MK_TOOL', 'PRET.G8.ENTREP.OF_GOODS_AND_SERVICES.MARKETING', 'Thinks the till or other shop equipment is a marketing tool.', '{"question":"Which is a marketing tool a small shop can use?","wrong_answer":"A cash register","correct_answer":"A poster, a social media page or a radio advert"}'::jsonb, 'Anything in a shop seems to help it sell.', 'Offer "A cash register" beside "A poster, a social media page or a radio advert" and ask the child to choose.', 'Sort shop items into equipment (till, shelves) and marketing tools (posters, signboards, social media pages, radio adverts, samples).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION.M_PT8_DS_MIDDLEMAN_BAD', 'PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION', 'Says intermediaries only raise the price and have no use.', '{"question":"What does a wholesaler do?","wrong_answer":"Nothing useful","correct_answer":"Buys in bulk and sells to retailers"}'::jsonb, 'The learner hears that middlemen raise prices and does not see the work they do.', 'Offer "Nothing useful" next to the right answer and ask the question again in a new context.', 'Follow a bag of maize from a farm to a shop: who stores, transports, breaks bulk and sells it near you?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION.M_PT8_DS_CHANNEL', 'PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION', 'Thinks the direct channel, producer to consumer, is the longest.', '{"question":"Which is the longest channel?","wrong_answer":"Producer to consumer","correct_answer":"Producer to wholesaler to retailer to consumer"}'::jsonb, 'The direct channel has the fewest steps but the learner reads "producer to consumer" as covering the most ground.', 'Offer "Producer to consumer" next to the right answer and ask the question again in a new context.', 'Draw each channel with arrows and count the steps; the most intermediaries make the longest channel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION.M_PT8_DS_ETHICS', 'PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION', 'Thinks hoarding goods to raise prices is clever business.', '{"question":"Which is ethical in distribution?","wrong_answer":"Hiding goods to raise the price","correct_answer":"Giving honest weights and fair prices"}'::jsonb, 'Higher prices feel like smart business, whatever the method.', 'Offer "Hiding goods to raise the price" next to the right answer and ask the question again in a new context.', 'Discuss the customer''s side of hoarding and false weights; customers leave and the law punishes it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION.M_PT8_DS_SERVICE_AGENT', 'PRET.G8.ENTREP.DISTRIBUTION_OF_GOODS_AN.DISTRIBUTION', 'Thinks services cannot have intermediaries, only goods can.', '{"question":"Which is an intermediary for a service?","wrong_answer":"None; services always go straight to the customer","correct_answer":"An M-Pesa agent or an insurance agent"}'::jsonb, 'Intermediaries are pictured as people moving goods in lorries.', 'Offer "None; services always go straight to the customer" beside "An M-Pesa agent or an insurance agent" and ask the child to choose.', 'List services the learner''s family uses and who delivers them: agents, booking offices, travel agents.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
